// Start node'undan path parametresini al
const path = $('Start').item.json.path;

// Klasör adını çıkart
const folderName = path.split('/').filter(x => x).pop();

// Tarih kısmını al
const datePart = folderName.split('_')[0];

// Tarihi formatla
let formattedDate;
if (datePart.length === 6) {
    formattedDate = `20${datePart.substring(0,2)}-${datePart.substring(2,4)}-${datePart.substring(4,6)}`;
} else if (datePart.length === 8) {
    formattedDate = `${datePart.substring(0,4)}-${datePart.substring(4,6)}-${datePart.substring(6,8)}`;
}

return [{ json: { formattedDate } }];

